    "text": "道具は余裕を持って用意してあるから。それより、当日の進め方をよく考えないと．．．うーん、自己紹介はいつものみたいに一人ずつ順番にしてもらうんだと時間かかっちゃうよね。ちょっとしたゲームとかのほうがいいか。",
