    "text": "うん。だから、新入社員のパソコンスキルを研修前に確認したらいいと思うんだ。ちょっとインターネットで探してみたら、パソコンのスキルがどれぐらいかを無料で簡単に測定してくれるテストがあるみたい。実技と知識の問題が含まれてるようなんだけど。内容が適当かどうか試しにやってみてくれる？サイトを教えるから。",
